import{_ as o}from"./chunks/settings-sw.pc.en.DiHbUhNv.js";import{_ as t,o as a,c as s,a5 as n}from"./chunks/framework.BjM_ivYE.js";const f=JSON.parse('{"title":"Software Update","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/software-update.md","filePath":"manual/gui/software-update.md","lastUpdated":1790646319000}'),r={name:"manual/gui/software-update.md"};function d(i,e,l,c,h,p){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="software-update" tabindex="-1">Software Update <a class="header-anchor" href="#software-update" aria-label="Permalink to &quot;Software Update&quot;">​</a></h1><p>Open <strong>Robot settings → Software update</strong>. The section updates two things: the software running on the robot, and this app itself.</p><p><img src="'+o+'" alt="Software update section"></p><h2 id="robot-software" tabindex="-1">Robot software <a class="header-anchor" href="#robot-software" aria-label="Permalink to &quot;Robot software&quot;">​</a></h2><p>The top of the panel shows two cards:</p><ul><li><code>Current robot</code> · Motion — <code>Version</code>, <code>Branch</code>, <code>Commit</code>, <code>Build</code> as reported by the robot.</li><li><code>Update file</code> — the package you are about to send: <code>Selected</code> file name, its <code>Version</code>, <code>Size</code>, and the <code>Target</code>.</li></ul><h3 id="choosing-a-package" tabindex="-1">Choosing a package <a class="header-anchor" href="#choosing-a-package" aria-label="Permalink to &quot;Choosing a package&quot;">​</a></h3><p>There are two ways to get a package onto the device.</p><p><strong>Online</strong> — the list below the cards shows the versions published for this app&#39;s release channel (<code>Online update</code> · <code>internet required</code>). Press <code>Check versions</code> (or <code>Refresh</code>) to fetch the list, then <code>Download</code> on the version you want. The download pulls the robot package onto this device, along with the app build on desktop. The row then shows the package size, plus <code>Latest</code> and <code>In use</code> badges where they apply. Downloaded files stay on the device, so you can download on the internet network and switch to the robot network before sending. <code>Remove</code> deletes a downloaded package. The <code>Release notes</code> under the list cover the selected version, or the version the robot is running when nothing is selected.</p><p><strong>From USB or a file</strong> — press <code>Load from USB or file</code>. The system file picker opens (a USB OTG drive shows up there like any other storage). Pick the package file; it must be named <code>RBQ-&lt;version&gt;.tar.gz</code> (the robot also accepts the <code>RBQ-&lt;version&gt;.zip</code> package). The <code>Update file</code> card fills in with the file&#39;s name, version, and size.</p><h3 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h3><p><code>Target</code> selects which robot PC receives the package: <code>Motion</code> (the robot IP you are connected to) or <code>Vision</code>. Vision matters only on older robots that have a separate vision PC. If the robot has no vision IP set — the <code>Vision IP</code> field in its profile on the hub, or <code>Vision PC IP (optional)</code> when you add it by address, both <a href="/RBQ/manual/gui/developer-mode.html">developer mode</a> — the app falls back to the default vision address and says so in a note.</p><h3 id="sending" tabindex="-1">Sending <a class="header-anchor" href="#sending" aria-label="Permalink to &quot;Sending&quot;">​</a></h3><ol><li>Press <code>Send robot software</code>.</li><li>The dialog <code>Send to the robot?</code> lists the file, size, and target. If the file name follows <code>RBQ-&lt;version&gt;.tar.gz</code>, the dialog warns that the robot will unpack and deploy it as soon as the transfer completes, replacing the running software. The dialog says files with any other name are only stored on the robot, but current robot software refuses them outright with a &quot;Rejected file name&quot; error — send only properly named packages.</li><li>Press <code>Send</code>. The progress bar shows the percentage, and <code>Cancel</code> aborts the transfer.</li><li>On success the panel shows <code>✓ Transfer complete</code> and asks <code>Deploy transfer complete — reboot now?</code>. With a <code>Vision</code> target the dialog only says the vision PC cannot be rebooted from the app and closes with <code>Check</code>.</li></ol><h3 id="reboot" tabindex="-1">Reboot <a class="header-anchor" href="#reboot" aria-label="Permalink to &quot;Reboot&quot;">​</a></h3><p>Robot software takes effect only after you reboot the robot. For a <code>Motion</code> target the reboot prompt offers <code>Later</code> and <code>Reboot now</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Rebooting cuts motor power and the robot will sag to the ground. The robot must be in the <strong>sitting</strong> state before you reboot — sit it down first and make sure it is resting on the floor, and do not move it during the reboot. If the robot is standing it ignores the reboot command, and the app shows no error. The app connection drops while the robot restarts. Reconnect afterwards and check that <code>Current robot</code> shows the new version.</p></div><p>The vision PC cannot be rebooted from the app. If the target was <code>Vision</code>, reboot that PC by hand.</p><h2 id="this-app" tabindex="-1">This app <a class="header-anchor" href="#this-app" aria-label="Permalink to &quot;This app&quot;">​</a></h2><p>The <strong>GUI Version</strong> line shows the version of the app you are running, followed by a badge:</p><ul><li>no badge — a release build,</li><li><code>NIGHTLY</code> — a nightly build (its list shows <code>Nightly builds</code> · <code>last 10 kept</code> instead of the release list),</li><li><code>LOCAL</code> — a local build with no release channel; it does not check for updates.</li></ul><p>Next to it, <code>Matches robot</code> (with a check mark) or <code>Differs from robot</code> compares the app version with the robot version. Keeping the two the same is the intended pairing.</p><p>Once the version list has loaded, an update button appears if a newer app is available:</p><ul><li><code>Update in store</code> — store installs (Google Play / App Store). The store app opens; install from there.</li><li><code>&lt;version&gt; Update</code> — APK and desktop installs. The app downloads the build and installs it (Android hands it to the system installer; desktop switches to the new build). <code>You&#39;re on the latest version</code> is shown when nothing newer exists.</li></ul><p>On desktop, <code>Install online</code> registers a build you downloaded but never installed, and <code>Use this build</code> switches to any downloaded build in the list.</p><p>Nightly builds only see nightly releases and release builds only see releases — the channel is fixed when the app is built.</p>',26)])])}const g=t(r,[["render",d]]);export{f as __pageData,g as default};
